/// Subset count per BC7 mode (0..7).
pub static G_BC7_NUM_SUBSETS: [u8; 8] = [3, 2, 3, 2, 1, 1, 1, 2];

/// Bits of partition index per mode. 0 means the mode has no partition field.
pub static G_BC7_PARTITION_BITS: [u8; 8] = [4, 6, 6, 6, 0, 0, 0, 6];

/// Base color-weight bit count per mode. Mode 4's index-selector bit, when
/// set, adds one on top of this.
pub static G_BC7_COLOR_INDEX_BITCOUNT: [u8; 8] = [3, 3, 2, 2, 2, 2, 4, 2];

/// Alpha-weight bit count per mode; 0 for modes that share one weight set
/// across color and alpha.
pub static G_BC7_ALPHA_INDEX_BITCOUNT: [u8; 8] = [0, 0, 0, 0, 3, 2, 4, 2];

/// Whether a mode carries p-bits: an extra bit per endpoint (or per subset,
/// when shared) that acts as the low bit of all of that endpoint's channels.
pub static G_BC7_MODE_HAS_P_BITS: [u8; 8] = [1, 1, 0, 1, 0, 0, 1, 1];

/// Whether a mode's p-bits are shared across the two endpoints of a subset
/// rather than one per endpoint.
pub static G_BC7_MODE_HAS_SHARED_P_BITS: [u8; 8] = [0, 1, 0, 0, 0, 0, 0, 0];

/// Bits per color channel of each endpoint, before any p-bit, per mode.
pub static G_BC7_COLOR_PRECISION: [u8; 8] = [4, 6, 5, 7, 5, 7, 7, 5];

/// Bits per alpha channel of each endpoint per mode; 0 when the mode has no
/// separate alpha endpoints.
pub static G_BC7_ALPHA_PRECISION: [i8; 8] = [0, 0, 0, 0, 6, 8, 7, 5];
